    }

    #[cfg(feature = "serde")]
    #[test]
    fn recorded_call_serializes() {
        let mut dl = DrawList::new();
        dl.begin_frame(2.0);
        dl.push_scissor([0.0, 0.0, 100.0, 100.0]);
        dl.start_recording();
